=== NotificationService.java
     1	package br.com.marealta;
     2	
     3	import java.util.ArrayList;
     4	import java.util.List;
     5	
     6	/**
     7	 * Envio de e-mails. Por enquanto nada sai de verdade: as mensagens ficam numa lista.
     8	 * Cada regra declara em que modo vale (sempre, só teste ou só fora do teste) e roda em ordem.
     9	 * Novas regras (horário, limite por hóspede) entram como mais um {@link Rule} na lista.
    10	 */
    11	public class NotificationService {
    12	    public static final String ARCHIVE_ADDRESS = "arquivo@pousadamarealta.com.br";
    13	    public static final String TEST_ADDRESS = "testes@pousadamarealta.com.br";
    14	
    15	    public enum Scope { ALWAYS, TEST_ONLY, NON_TEST_ONLY }
    16	
    17	    /** Mensagem em construção, que as regras podem alterar, bloquear ou acompanhar de cópias. */
    18	    public static class Draft {
    19	        public String to;
    20	        public String subject;
    21	        public String body;
    22	        public boolean blocked;
    23	        public final List<Draft> extras = new ArrayList<>();
    24	
    25	        Draft(String to, String subject, String body) {
    26	            this.to = to;
    27	            this.subject = subject;
    28	            this.body = body;
    29	        }
    30	    }
    31	
    32	    public interface Rule {
    33	        Scope scope();
    34	        void apply(Draft draft);
    35	    }
    36	
    37	    private final boolean testMode;
    38	    private final List<Rule> rules;
    39	    private final List<Message> sent = new ArrayList<>();
    40	
    41	    public NotificationService(boolean testMode) {
    42	        this.testMode = testMode;
    43	        this.rules = List.of(
    44	                // 1. endereço inválido: bloqueia (com o endereço original)
    45	                new Rule() {
    46	                    public Scope scope() { return Scope.ALWAYS; }
    47	                    public void apply(Draft d) {
    48	                        if (!EmailValidator.isValid(d.to)) d.blocked = true;
    49	                    }
    50	                },
    51	                // 2. modo de teste: nunca sai para o endereço real
    52	                new Rule() {
    53	                    public Scope scope() { return Scope.TEST_ONLY; }
    54	                    public void apply(Draft d) {
    55	                        if (d.blocked) return;
    56	                        d.body = "Destinatário original: " + d.to + "\n" + d.body;
    57	                        d.subject = "[TESTE] " + d.subject;
    58	                        d.to = TEST_ADDRESS;
    59	                    }
    60	                },
    61	                // 3. cópia para o arquivo do contador
    62	                new Rule() {
    63	                    public Scope scope() { return Scope.NON_TEST_ONLY; }
    64	                    public void apply(Draft d) {
    65	                        if (d.blocked) return;
    66	                        d.extras.add(new Draft(ARCHIVE_ADDRESS, "[Cópia] " + d.subject, d.body));
    67	                    }
    68	                });
    69	    }
    70	
    71	    public boolean isTestMode() { return testMode; }
    72	
    73	    public synchronized void sendEmail(String to, String subject, String body) {
    74	        Draft draft = new Draft(to, subject, body);
    75	        for (Rule r : rules) {
    76	            boolean applies = switch (r.scope()) {
    77	                case ALWAYS -> true;
    78	                case TEST_ONLY -> testMode;
    79	                case NON_TEST_ONLY -> !testMode;
    80	            };
    81	            if (applies) r.apply(draft);
    82	        }
    83	        record(draft);
    84	        for (Draft extra : draft.extras) record(extra);
    85	    }
    86	
    87	    private void record(Draft d) {
    88	        sent.add(new Message(sent.size() + 1, "EMAIL", d.to, d.subject, d.body, d.blocked ? "BLOCKED" : "SENT"));
    89	    }
    90	
    91	    public synchronized List<Message> messages() {
    92	        return List.copyOf(sent);
    93	    }
    94	}
