     1	package br.com.marealta;
     2	
     3	public final class EmailValidator {
     4	    private EmailValidator() {}
     5	
     6	    /** Um único @, algo antes dele e, depois, um nome com ponto no meio (sem rótulos vazios). */
     7	    public static boolean isValid(String email) {
     8	        if (email == null) return false;
     9	        for (int i = 0; i < email.length(); i++) {
    10	            if (Character.isWhitespace(email.charAt(i))) return false;
    11	        }
    12	        int at = email.indexOf('@');
    13	        if (at <= 0 || at != email.lastIndexOf('@')) return false;
    14	        String domain = email.substring(at + 1);
    15	        if (!domain.contains(".")) return false;
    16	        for (String label : domain.split("\\.", -1)) {
    17	            if (label.isEmpty()) return false;
    18	        }
    19	        return true;
    20	    }
    21	}
