    42	                ctx -> json(ctx, 200, reservationJson(service.checkIn(ctx.pathParam("id")))));
    43	        app.post("/reservations/{id}/check-out",
    44	                ctx -> json(ctx, 200, documentJson(service.checkOut(ctx.pathParam("id")))));
    45	        app.get("/reservations/{id}/document",
    46	                ctx -> json(ctx, 200, documentJson(service.paidReservation(ctx.pathParam("id")))));
    47	
    48	        app.get("/messages", ctx -> json(ctx, 200, notifications.messages().stream().map(App::messageJson).toList()));
    49	
    50	        app.get("/reports/occupancy", ctx -> {
    51	            LocalDate date = parseDate(ctx.queryParam("date"), "date");
    52	            csv(ctx, service.occupancyCsv(date));
    53	        });
    54	        app.get("/reports/revenue", ctx -> {
    55	            String m = ctx.queryParam("month");
    56	            if (m == null || m.isBlank()) throw ApiException.invalid("Informe o mês (month=AAAA-MM)");
    57	            YearMonth month;
