    59	                month = YearMonth.parse(m);
    60	            } catch (DateTimeParseException e) {
    61	                throw ApiException.invalid("Mês inválido: " + m);
    62	            }
    63	            csv(ctx, service.revenueCsv(month));
    64	        });
