    70	    private static ReservationService.CreateCommand parseCreate(Context ctx) {
    71	        JsonNode body;
    72	        try {
    73	            body = MAPPER.readTree(ctx.body());
    74	        } catch (JsonProcessingException e) {
    75	            throw ApiException.invalid("O corpo não é um JSON válido");
    76	        }
    77	        if (body == null || !body.isObject()) throw ApiException.invalid("O corpo deve ser um objeto JSON");
    78	
    79	        int room = intField(body, "roomNumber");
    80	        String name = textField(body, "guestName");
    81	        String email = textField(body, "guestEmail");
    82	        String cpf = textField(body, "guestCpf");
    83	        LocalDate in = parseDate(textField(body, "checkIn"), "checkIn");
    84	        LocalDate out = parseDate(textField(body, "checkOut"), "checkOut");
    85	        int guests = intField(body, "guests");
    86	        RatePlan plan;
    87	        try {
    88	            plan = RatePlan.valueOf(textField(body, "ratePlan"));
    89	        } catch (IllegalArgumentException e) {
    90	            throw ApiException.invalid("Plano de tarifa inválido");
    91	        }
    92	        return new ReservationService.CreateCommand(room, name, email, cpf, in, out, guests, plan);
    93	    }
    94	
    95	    private static String textField(JsonNode body, String name) {
    96	        JsonNode n = body.get(name);
    97	        if (n == null || n.isNull()) throw ApiException.invalid("Campo obrigatório: " + name);
    98	        if (!n.isTextual() || n.asText().isBlank()) throw ApiException.invalid("Campo inválido: " + name);
    99	        return n.asText();
   100	    }
   101	
   102	    private static int intField(JsonNode body, String name) {
   103	        JsonNode n = body.get(name);
   104	        if (n == null || n.isNull()) throw ApiException.invalid("Campo obrigatório: " + name);
   105	        if (!n.isIntegralNumber() || !n.canConvertToInt()) throw ApiException.invalid("Campo inválido: " + name);
   106	        return n.asInt();
   107	    }
   108	
   109	    private static LocalDate parseDate(String s, String field) {
   110	        if (s == null || s.isBlank()) throw ApiException.invalid("Informe a data: " + field);
   111	        try {
   112	            return LocalDate.parse(s);
   113	        } catch (DateTimeParseException e) {
   114	            throw ApiException.invalid("Data inválida em " + field + ": " + s);
   115	        }
   116	    }
   117	
   118	    // ---- saída ----
   119	
   120	    private static void json(Context ctx, int status, Object body) {
   121	        try {
   122	            ctx.status(status).contentType("application/json").result(MAPPER.writeValueAsString(body));
   123	        } catch (JsonProcessingException e) {
   124	            throw new IllegalStateException(e);
   125	        }
   126	    }
   127	
   128	    private static void csv(Context ctx, String body) {
   129	        ctx.status(200).contentType("text/csv; charset=utf-8").result(body.getBytes(java.nio.charset.StandardCharsets.UTF_8));
   130	    }
   131	
   132	    private static void error(Context ctx, int status, String code, String message) {
   133	        Map<String, Object> m = new LinkedHashMap<>();
   134	        m.put("error", code);
   135	        m.put("message", message);
   136	        json(ctx, status, m);
   137	    }
   138	
   139	    private static Map<String, Object> roomJson(Room r) {
   140	        Map<String, Object> m = new LinkedHashMap<>();
