   177	        m.put("checkIn", r.checkIn.toString());
   178	        m.put("checkOut", r.checkOut.toString());
   179	        m.put("nights", r.nights);
   180	        m.put("subtotal", r.subtotal);
   181	        m.put("discount", r.discount);
