    11	public class ReservationService {
    12	    public static final List<Room> ROOMS = List.of(
    13	            new Room(101, RoomType.STANDARD, 2, Money.of("249.90")),
    14	            new Room(102, RoomType.STANDARD, 2, Money.of("249.90")),
    15	            new Room(201, RoomType.DELUXE, 3, Money.of("389.90")),
    16	            new Room(202, RoomType.DELUXE, 3, Money.of("389.90")),
    17	            new Room(301, RoomType.SUITE, 4, Money.of("579.90")));
