    19	    public record CreateCommand(int roomNumber, String guestName, String guestEmail, String guestCpf,
    20	                                LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan) {}
    21	
    22	    private final NotificationService notifications;
    23	    private final List<Reservation> reservations = new ArrayList<>();
    24	
    25	    public ReservationService(NotificationService notifications) {
    26	        this.notifications = notifications;
    27	    }
    28	
    29	    public List<Room> rooms() { return ROOMS; }
    30	
    31	    public Optional<Room> findRoom(int number) {
    32	        return ROOMS.stream().filter(r -> r.number() == number).findFirst();
    33	    }
    34	
    35	    public synchronized Reservation create(CreateCommand c) {
    36	        if (!c.checkOut().isAfter(c.checkIn())) throw ApiException.invalid("A saída deve ser depois da entrada");
    37	        if (c.guests() < 1) throw ApiException.invalid("É preciso pelo menos um hóspede");
    38	        Room room = findRoom(c.roomNumber()).orElseThrow(() -> ApiException.roomNotFound(c.roomNumber()));
    39	        if (c.guests() > room.capacity()) {
    40	            throw ApiException.capacity("O quarto " + room.number() + " comporta no máximo " + room.capacity() + " pessoas");
    41	        }
    42	        boolean taken = reservations.stream().anyMatch(r -> r.room.number() == room.number()
    43	                && r.status != ReservationStatus.CANCELLED && r.overlaps(c.checkIn(), c.checkOut()));
    44	        if (taken) throw ApiException.unavailable("O quarto " + room.number() + " já está reservado em alguma das noites");
    45	        Pricing.Quote q = Pricing.quote(room, c.checkIn(), c.checkOut(), c.ratePlan());
    46	        Reservation r = new Reservation(reservations.size() + 1, room, c.guestName(), c.guestEmail(),
    47	                c.guestCpf(), c.checkIn(), c.checkOut(), c.guests(), c.ratePlan(), q);
    48	        reservations.add(r);
    49	        return r;
    50	    }
    51	
    52	    public synchronized Reservation get(String id) {
    53	        int n;
    54	        try {
    55	            n = Integer.parseInt(id);
    56	        } catch (NumberFormatException e) {
    57	            throw ApiException.reservationNotFound(id);
    58	        }
    59	        if (n < 1 || n > reservations.size()) throw ApiException.reservationNotFound(id);
    60	        return reservations.get(n - 1);
    61	    }
    62	
    63	    public synchronized Reservation confirm(String id) {
    64	        Reservation r = get(id);
    65	        require(r, ReservationStatus.PENDING, "Só é possível confirmar uma reserva pendente");
    66	        r.status = ReservationStatus.CONFIRMED;
    67	        r.amountPaid = r.total;
    68	        notifications.sendEmail(r.guestEmail, Receipt.confirmationSubject(), Receipt.confirmationBody(r));
    69	        return r;
    70	    }
    71	
    72	    public synchronized Reservation checkIn(String id) {
    73	        Reservation r = get(id);
    74	        require(r, ReservationStatus.CONFIRMED, "Só é possível fazer check-in de uma reserva confirmada");
    75	        r.status = ReservationStatus.CHECKED_IN;
    76	        return r;
    77	    }
    78	
    79	    public synchronized Reservation checkOut(String id) {
    80	        Reservation r = get(id);
    81	        require(r, ReservationStatus.CHECKED_IN, "Só é possível fazer check-out de uma reserva com check-in");
    82	        r.status = ReservationStatus.CHECKED_OUT;
    83	        return r;
    84	    }
    85	
    86	    public synchronized Reservation cancel(String id) {
    87	        Reservation r = get(id);
    88	        if (r.status != ReservationStatus.PENDING && r.status != ReservationStatus.CONFIRMED) {
    89	            throw ApiException.notAllowed("Só é possível cancelar uma reserva pendente ou confirmada");
    90	        }
    91	        r.refund = (r.status == ReservationStatus.CONFIRMED && r.ratePlan == RatePlan.STANDARD)
    92	                ? r.amountPaid : Money.round(BigDecimal.ZERO);
    93	        r.status = ReservationStatus.CANCELLED;
    94	        return r;
    95	    }
    96	
    97	    /** Reserva paga, para a segunda via do comprovante. */
    98	    public synchronized Reservation paidReservation(String id) {
    99	        Reservation r = get(id);
   100	        if (!r.status.isPaid()) {
   101	            throw ApiException.notAllowed("O comprovante só existe para reserva paga");
   102	        }
   103	        return r;
   104	    }
   105	
   106	    private void require(Reservation r, ReservationStatus expected, String message) {
   107	        if (r.status != expected) throw ApiException.notAllowed(message);
   108	    }
   109	
   110	    // ---- relatórios ----
   111	
   112	    public synchronized String occupancyCsv(LocalDate night) {
   113	        List<Reservation> occupied = reservations.stream()
   114	                .filter(r -> r.status.isPaid() && !night.isBefore(r.checkIn) && night.isBefore(r.checkOut))
   115	                .sorted(Comparator.comparingInt((Reservation r) -> r.room.number()).thenComparingInt(r -> r.id))
   116	                .toList();
   117	        StringBuilder sb = new StringBuilder("room,type,reservation,check_in,check_out\n");
   118	        for (Reservation r : occupied) {
   119	            sb.append(r.room.number()).append(',').append(r.room.type()).append(',').append(r.id).append(',')
   120	                    .append(r.checkIn).append(',').append(r.checkOut).append('\n');
   121	        }
   122	        long rooms = occupied.stream().map(r -> r.room.number()).distinct().count();
   123	        sb.append("total,").append(rooms).append('/').append(ROOMS.size()).append('\n');
   124	        return sb.toString();
   125	    }
   126	
   127	    public synchronized String revenueCsv(YearMonth month) {
   128	        List<Reservation> list = reservations.stream()
   129	                .filter(r -> YearMonth.from(r.checkIn).equals(month) && r.netAmount().signum() > 0)
   130	                .sorted(Comparator.comparing((Reservation r) -> r.checkIn).thenComparingInt(r -> r.id))
   131	                .toList();
   132	        StringBuilder sb = new StringBuilder("reservation,room,check_in,check_out,status,amount\n");
   133	        BigDecimal sum = Money.round(BigDecimal.ZERO);
   134	        for (Reservation r : list) {
   135	            sb.append(r.id).append(',').append(r.room.number()).append(',').append(r.checkIn).append(',')
   136	                    .append(r.checkOut).append(',').append(r.status).append(',')
   137	                    .append(r.netAmount().toPlainString()).append('\n');
   138	            sum = sum.add(r.netAmount());
   139	        }
   140	        sb.append("total,").append(Money.round(sum).toPlainString()).append('\n');
   141	        return sb.toString();
   142	    }
   143	}
