     1	package br.com.marealta;
     2	
     3	import java.math.BigDecimal;
     4	import java.math.RoundingMode;
     5	import java.text.DecimalFormat;
     6	import java.text.DecimalFormatSymbols;
     7	import java.util.Locale;
     8	
     9	/** Utilitários de dinheiro: tudo em BigDecimal com 2 casas, arredondamento meio para o par. */
    10	public final class Money {
    11	    private Money() {}
    12	
    13	    public static BigDecimal round(BigDecimal v) {
    14	        return v.setScale(2, RoundingMode.HALF_EVEN);
    15	    }
    16	
    17	    public static BigDecimal of(String v) {
    18	        return round(new BigDecimal(v));
    19	    }
    20	
    21	    /** Formato brasileiro: R$ 1.234,56 */
    22	    public static String brl(BigDecimal v) {
    23	        DecimalFormatSymbols sym = new DecimalFormatSymbols(Locale.ROOT);
    24	        sym.setDecimalSeparator(',');
    25	        sym.setGroupingSeparator('.');
    26	        DecimalFormat df = new DecimalFormat("#,##0.00", sym);
    27	        df.setRoundingMode(RoundingMode.HALF_EVEN);
    28	        return "R$ " + df.format(round(v));
    29	    }
    30	}
