=== src/main/java/br/com/marealta/Pricing.java
     1	package br.com.marealta;
     2	
     3	import java.math.BigDecimal;
     4	import java.time.LocalDate;
     5	import java.time.Month;
     6	
     7	/** Regras de preço: alta temporada e plano de tarifa. */
     8	public final class Pricing {
     9	    private Pricing() {}
    10	
    11	    private static final BigDecimal HIGH_SEASON_FACTOR = new BigDecimal("1.20");
    12	    private static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
    13	
    14	    public record Quote(int nights, BigDecimal subtotal, BigDecimal discount, BigDecimal total) {}
    15	
    16	    /** Alta temporada: 15/12 até o fim de fevereiro, e julho inteiro. */
    17	    public static boolean isHighSeason(LocalDate night) {
    18	        Month m = night.getMonth();
    19	        return m == Month.JULY
    20	                || m == Month.JANUARY
    21	                || m == Month.FEBRUARY
    22	                || (m == Month.DECEMBER && night.getDayOfMonth() >= 15);
    23	    }
    24	
    25	    public static BigDecimal nightPrice(Room room, LocalDate night) {
    26	        BigDecimal rate = room.nightlyRate();
    27	        return Money.round(isHighSeason(night) ? rate.multiply(HIGH_SEASON_FACTOR) : rate);
    28	    }
    29	
    30	    public static Quote quote(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan plan) {
    31	        BigDecimal subtotal = Money.round(BigDecimal.ZERO);
    32	        int nights = 0;
    33	        for (LocalDate d = checkIn; d.isBefore(checkOut); d = d.plusDays(1)) {
    34	            subtotal = Money.round(subtotal.add(nightPrice(room, d)));
    35	            nights++;
    36	        }
    37	        BigDecimal discount = plan == RatePlan.NON_REFUNDABLE
    38	                ? Money.round(subtotal.multiply(NON_REFUNDABLE_DISCOUNT))
    39	                : Money.round(BigDecimal.ZERO);
    40	        BigDecimal total = Money.round(subtotal.subtract(discount));
    41	        return new Quote(nights, subtotal, discount, total);
    42	    }
    43	}
